import { icon } from './icons.js';
import { validateSnapshot, filterSchools, filterResults, pageItems, readOfficialFollows, directoryCsv, officialSports, trustedSource } from './official-domain.js';
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const $=selector=>document.querySelector(selector);
const count=n=>n.toLocaleString('en-US');
const period=s=>s==='2026-2028'?'2026–28':s==='2025-2026'?'2025–26':s==='2024-2025'?'2024–25':s==='2026-2027'?'2026–27':s;
const dateTime=value=>new Intl.DateTimeFormat('en-US',{timeZone:'America/Chicago',month:'short',day:'numeric',year:'numeric',hour:'numeric',minute:'2-digit',timeZoneName:'short'}).format(new Date(value));
const external=(url,label,className='')=>trustedSource(url)?`<a class="${className}" href="${esc(url)}" target="_blank" rel="noopener noreferrer">${label} ↗</a>`:'';
const initials=name=>name.split(/\s+/).filter(Boolean).slice(0,2).map(s=>s[0]).join('').toUpperCase();
const crest=(school,big=false)=>`<span class="crest ${big?'big':''}" style="--team:#496954" aria-label="School initials; not an official logo">${esc(initials(school.name))}</span>`;
const pages={
  overview:['Overview','Real schools. Real results','Explore UIL school listings and historical championship results, with a source behind every record.'],
  rankings:['Rankings','Earn the numbers. Then rank','Statewide power ratings are not available yet. Explore the documented championship outcomes below.'],
  games:['Scores','The results, on the record','Official football championship finals from past seasons. Live and regular-season scores are not connected.'],
  teams:['Schools','Find your school','Browse the UIL realignment directory. Listings describe programs and districts, not verified team rosters.'],
  news:['News & sources','Straight from the source','Open the official UIL publications behind this release. A news feed is not connected yet.'],
  favorites:['My schools','Your schools. All in one place','Follow real schools in this browser. Your saved schools stay separate from demo teams.'],
};

export async function startOfficialApp(raw) {
  const data=validateSnapshot(raw);
  const byId=new Map(data.schools.map(s=>[s.id,s]));
  const sources=new Map(data.sources.map(s=>[s.id,s]));
  const directorySource=sources.get('uil-alignment-2026');
  const resultSource=sources.get('uil-football-archives');
  let storage;try{storage=window.localStorage;}catch{storage={getItem:()=>null,setItem:()=>{throw Error('Storage blocked');}};}
  const state={view:'overview',sport:'football',classification:'all',district:'all',format:'all',query:'',page:1,season:'2025-2026',gameStatus:'final',modal:null,
    follows:readOfficialFollows(storage,new Set(byId.keys()))};
  const sportName=()=>officialSports.find(s=>s.id===state.sport)?.name||'Schools';
  const resultView=()=>['rankings','games'].includes(state.view);
  const selectedSchools=()=>filterSchools(data.schools,state);
  const selectedResults=()=>{if(resultView())return filterResults(data.games,state);const ids=new Set(selectedSchools().map(s=>s.id));return filterResults(data.games,{sport:state.sport,season:state.season}).filter(g=>ids.has(g.teamAId)||ids.has(g.teamBId));};
  const follow=school=>`<button class="fav ${state.follows.has(school.id)?'saved':''}" data-action="follow" data-id="${school.id}" aria-label="${state.follows.has(school.id)?'Unfollow':'Follow'} ${esc(school.name)}" aria-pressed="${state.follows.has(school.id)}">${state.follows.has(school.id)?'★':'☆'}</button>`;
  const sourceLink=(source,label='View UIL source')=>external(source.url,label,'source-link');
  function empty(title,text,reset=true){return `<section class="empty"><div class="empty-icon">◇</div><h3>${title}</h3><p>${text}</p>${reset?'<button class="secondary-button" data-action="clear">Clear filters</button>':'<button class="secondary-button" data-action="sources">Sources & coverage</button>'}</section>`;}
  function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),2600);}
  function modal(title,body,type,id){state.modal={type,id};$('#modal-content').innerHTML=`<div class="modal-eyebrow">PUBLIC UIL RECORDS / INDEPENDENT APP</div><h2 class="modal-title" id="modal-title">${title}</h2>${body}`;if(!$('#modal').open)$('#modal').showModal();}
  function closeModal(){$('#modal').close();state.modal=null;}
  function nav(){
    $('#nav').innerHTML=Object.entries(pages).map(([id,p])=>`<a href="#${id}" class="nav-item ${state.view===id?'active':''}" ${state.view===id?'aria-current="page"':''}>${icon(id)}<span>${p[0]}</span>${id==='favorites'?`<span class="count">${state.follows.size}</span>`:''}</a>`).join('');
  }
  function shell(){
    nav();const p=pages[state.view];$('#breadcrumb').textContent=p[0];$('#page-title').innerHTML=esc(p[1])+'<span>.</span>';$('#page-subtitle').textContent=p[2];document.title=`${p[0]} · Texas High School Sports`;
    $('#sports').innerHTML=officialSports.map(s=>`<button class="sport-tab ${s.id===state.sport?'active':''}" data-action="sport" data-id="${s.id}" aria-pressed="${s.id===state.sport}">${icon(s.icon,18)}${s.name}</button>`).join('');
    $('#classification').setAttribute('aria-label',resultView()?'Result-season classification':'Classification (2026–28)');
    const selectedClass=state.classification;
    $('#classification').innerHTML=`<option value="all">${resultView()?'All result classes':'All classes (2026–28)'}</option>`+['6A','5A','4A','3A','2A','1A'].map(c=>`<option>${c}</option>`).join('');$('#classification').value=selectedClass;
    const districts=[...new Set(data.schools.map(s=>s.districts[state.sport]).filter(n=>n!=null))].sort((a,b)=>a-b);
    $('#region').hidden=resultView()||state.sport==='all'||districts.length===0;
    $('#region').innerHTML='<option value="all">All districts</option>'+districts.map(d=>`<option value="${d}">District ${d}</option>`).join('');$('#region').value=state.district;
    $('#gender').hidden=!['football','all'].includes(state.sport);
    $('#gender').value=state.format;
    $('.season-label').textContent=resultView()?`${period(state.season)} · HISTORICAL FINALS`:'2026–28 UIL ALIGNMENT';
    $('.reset-filters').hidden=!(state.query||state.classification!=='all'||state.district!=='all'||state.format!=='all');
    $('footer>span:last-child').innerHTML=`Snapshot: ${esc(dateTime(data.fetchedAt))} <button data-action="sources">Sources ↗</button>`;
  }
  function coverageCard(){return `<section class="forecast official-coverage"><div class="eyebrow"><span>KNOW YOUR COVERAGE</span><span>UIL SOURCES</span></div><h2>Every record has a source.</h2><p>${count(data.schools.length)} schools in the 2026–28 directory. ${data.games.length} historical football finals across two seasons.</p><div class="coverage-list"><div><span>School & district listings</span><strong>Available</strong></div><div><span>Historical championship finals</span><strong>Available</strong></div><div><span>Live / regular-season scores</span><strong>Not connected</strong></div><div><span>Ratings & predictions</span><strong>Not available</strong></div></div><p class="disclaimer">UIL public records. This app is independent and is not affiliated with or endorsed by UIL.</p><button data-action="sources">Explore sources & coverage ${icon('arrow',13)}</button></section>`;}
  function scoreCard(game){const a=byId.get(game.teamAId),b=byId.get(game.teamBId);return `<button class="score-card official-score" data-action="game" data-id="${game.id}" aria-label="View ${esc(game.teamAName)} vs. ${esc(game.teamBName)}"><div class="score-head"><span class="final-tag">FINAL · ${period(game.season)}</span><span>${esc(game.classification)} · DIV ${game.division}</span></div><div class="team-line">${crest(a)}<span class="name">${esc(game.teamAName)}</span><span class="score">${game.teamAScore}</span></div><div class="team-line">${crest(b)}<span class="name">${esc(game.teamBName)}</span><span class="score">${game.teamBScore}</span></div><div class="context"><span>State championship · ${game.footballFormat==='6-Man'?'6-man':'11-man'}</span><span>UIL archive ↗</span></div></button>`;}
  function sourceCards(){return `<div class="source-card-grid">${data.sources.map(source=>`<article class="source-card"><div class="source-kind">${source.kind==='school-directory'?'SCHOOL DIRECTORY':'HISTORICAL RESULTS'} · UIL</div><h3>${esc(source.title)}</h3><p>${source.kind==='school-directory'?'Classifications, reported enrollment, and district listings for football, basketball, and volleyball.':'Twelve football state championship finals per season, covering 2025–26 and 2024–25.'}</p><small>${esc(source.period)} · Retrieved ${esc(dateTime(source.fetchedAt))}</small>${sourceLink(source,'Read official publication')}</article>`).join('')}</div>`;}
  function schoolTable(schools,limit=8){const list=schools.slice(0,limit);return `<section class="panel"><div class="panel-header"><h2>School directory<small>2026–28 UIL LISTINGS · ALPHABETICAL</small></h2><span class="scope-chip">${count(schools.length)} schools</span></div>${list.length?`<div class="table-scroll"><table><thead><tr><th scope="col">School</th><th scope="col">Class</th><th scope="col">${state.sport==='all'?'Programs':'District'}</th><th scope="col">Follow</th></tr></thead><tbody>${list.map(s=>`<tr><td><button class="table-team" data-action="school" data-id="${s.id}">${crest(s)}<span><strong>${esc(s.name)}</strong><small>UIL directory · Source page ${s.sourcePage}</small></span></button></td><td>${s.classification}</td><td>${state.sport==='all'?Object.keys(s.districts).length:s.districts[state.sport]??'—'}</td><td>${follow(s)}</td></tr>`).join('')}</tbody></table></div>`:empty('No schools found','Try another sport, class, district, or school name.')}<div class="panel-bottom"><span>${sourceLink(directorySource,'UIL alphabetical listing')}</span><button data-action="view-schools">Browse all schools →</button></div></section>`;}
  function overview(){const schools=selectedSchools(),games=selectedResults();return `<section><div class="section-heading"><h2>Championship scoreboard <small>${period(state.season)} · HISTORICAL</small></h2><button class="section-link" data-action="view-games">All results →</button></div><div class="live-grid">${games.length?games.slice(0,3).map(scoreCard).join(''):empty('No results imported for this view','The current snapshot includes football championship finals only. Other sports and regular-season scores are not connected.',false)}</div></section><section class="stats"><div class="stat"><div class="stat-label">Listed schools · ${state.sport==='all'?'All UIL':sportName()}</div><div class="stat-value">${count(schools.length)}<small>schools</small></div></div><div class="stat"><div class="stat-label">${period(state.season)} finals in view</div><div class="stat-value">${games.length}<small>results</small></div></div><div class="stat"><div class="stat-label">Power ratings</div><div class="stat-value">—<small>not available</small></div></div><div class="stat"><div class="stat-label">Following</div><div class="stat-value">${state.follows.size}<small>schools</small></div></div></section><div class="content-grid">${schoolTable(schools)}<aside class="right-rail">${coverageCard()}<section class="mini-panel"><h3>Real data, clearly labeled</h3><p>Historical results retain their original class. Current school profiles use the separate 2026–28 alignment. No missing values are replaced with sample ratings.</p></section></aside></div><section class="news-section"><div class="section-heading"><h2>From the source <small>OFFICIAL PUBLICATIONS</small></h2><button class="section-link" data-action="sources">Coverage details →</button></div>${sourceCards()}</section>`;}
  function resultToolbar(){return `<div class="result-toolbar"><label for="result-season">Result season</label><select id="result-season" aria-label="Result season">${[['2025-2026','2025–26 championship finals'],['2024-2025','2024–25 championship finals'],['2026-2027','2026–27 · No scores connected']].map(([id,label])=>`<option value="${id}" ${state.season===id?'selected':''}>${label}</option>`).join('')}</select><span>Class filters use the result season, not current alignment.</span></div>`;}
  function gamesView(){const games=selectedResults();return `<div class="view-intro"><div><h2>The final score. The original source.</h2><p>${data.games.length} imported football finals across two past seasons. No current-season feed.</p></div><button class="secondary-button" data-action="sources">Data coverage ↗</button></div>${resultToolbar()}<div class="view-tabs" aria-label="Game status">${[['final','Final results'],['live','Live'],['upcoming','Upcoming']].map(([id,label])=>`<button data-action="game-status" data-id="${id}" class="${state.gameStatus===id?'active':''}" aria-pressed="${state.gameStatus===id}">${label}</button>`).join('')}</div><div class="games-list">${state.gameStatus==='final'?(games.length?games.map(scoreCard).join(''):empty('No imported results match this view','Try Football and a 2025–26 or 2024–25 result season. This is a limited championship archive, not a full-season scoreboard.',false)):empty(`${state.gameStatus==='live'?'Live scores':'Upcoming schedules'} are not connected`,'Only sourced, completed championship finals are available in this release.',false)}</div><p class="method-note">Scores come from the UIL Football State Archives. Team order reflects champion and runner-up; it does not indicate home and away. No simulation runs in this view. ${sourceLink(resultSource)}</p>`;}
  function rankingsView(){const games=selectedResults();return `<section class="availability-note"><span class="notice-icon">i</span><div><h2>Power rankings are not available yet.</h2><p>Championship-only results cannot establish a full-season ranking, win–loss record, or reliable forecast. Schools remain unranked until sufficient results are available.</p></div></section>${resultToolbar()}<section class="panel"><div class="panel-header"><h2>State champions<small>${period(state.season)} · HISTORICAL OUTCOMES, NOT A POWER RANKING</small></h2><span class="scope-chip">UIL archive</span></div>${games.length?`<div class="table-scroll"><table><thead><tr><th scope="col">Class / Division</th><th scope="col">Champion</th><th scope="col">Runner-up</th><th scope="col">Final</th></tr></thead><tbody>${games.map(g=>`<tr><td>${g.classification} · D${g.division}${g.footballFormat==='6-Man'?' · 6-man':''}</td><td><button class="plain-team" data-action="school" data-id="${g.teamAId}">${esc(g.teamAName)}</button></td><td><button class="plain-team" data-action="school" data-id="${g.teamBId}">${esc(g.teamBName)}</button></td><td><button class="result-score" data-action="game" data-id="${g.id}">${g.teamAScore}–${g.teamBScore} ↗</button></td></tr>`).join('')}</tbody></table></div>`:empty('No championship records in this view','Only football finals from 2025–26 and 2024–25 are imported.',false)}<div class="panel-bottom">${sourceLink(resultSource,'Verify against UIL')}</div></section>`;}
  function schoolCard(s){return `<article class="team-card official-school"><div class="team-card-head">${crest(s,true)}${follow(s)}</div><h3><button data-action="school" data-id="${s.id}">${esc(s.name)}</button></h3><p>UIL ${s.classification} · 2026–28 alignment</p><div class="school-programs">${Object.entries(s.districts).map(([id,d])=>`<span>${esc(officialSports.find(x=>x.id===id).name)} <strong>D${d}</strong></span>`).join('')||'<span>No listed program districts</span>'}</div><button class="detail-button" data-action="school" data-id="${s.id}"><span>School profile & sources</span><span>→</span></button></article>`;}
  function schoolsView(saved=false){const full=selectedSchools().filter(s=>!saved||state.follows.has(s.id));const page=pageItems(full,state.page);state.page=page.page;return `<div class="view-intro"><div><h2>${saved?'Your school shortlist.':'Every school starts with a name.'}</h2><p>${count(full.length)} matching schools · ${count(data.schools.length)} total UIL directory entries · 2026–28</p></div><button class="primary-button" data-action="export">${icon('download',15)}Export directory</button></div><p class="directory-note">${state.sport==='all'?'Showing all schools listed in the UIL document, including entries without program districts.':'Showing schools with a '+esc(sportName())+' district listing. These are program listings, not verified varsity rosters.'} City, mascot, full-season records, and ratings are not supplied by this source.</p><div class="team-grid">${page.items.length?page.items.map(schoolCard).join(''):empty(saved?'No followed schools match this view':'No schools found',saved?'Follow a school with ☆, or choose All schools and clear your filters.':state.sport==='soccer'?'Soccer district data has not been imported. Choose another sport or All schools.':'Try another sport, class, district, or school name.')}</div>${page.total?`<nav class="pagination" aria-label="School directory pages"><span>Showing ${count((page.page-1)*24+1)}–${count(Math.min(page.page*24,page.total))} of ${count(page.total)}</span><div><button class="secondary-button" data-action="page" data-id="${page.page-1}" ${page.page===1?'disabled':''}>← Previous</button><span>Page ${page.page} / ${page.pages}</span><button class="secondary-button" data-action="page" data-id="${page.page+1}" ${page.page===page.pages?'disabled':''}>Next →</button></div></nav>`:''}`;}
  function newsView(){return `<div class="view-intro"><div><h2>Read the records. Check the source.</h2><p>Official publications behind the school directory and historical results. These are source documents, not a live news feed.</p></div></div>${sourceCards()}<section class="availability-note"><span class="notice-icon">i</span><div><h2>A news feed is not connected.</h2><p>Future coverage will show the original publisher, article link, and publication time. No fictional news is presented in public-data mode.</p></div></section><button class="secondary-button" data-action="sources">View retrieval details & coverage</button>`;}
  function renderContent(){const views={overview,rankings:rankingsView,games:gamesView,teams:()=>schoolsView(false),favorites:()=>schoolsView(true),news:newsView};$('#content').innerHTML=views[state.view]();}
  function render(){shell();renderContent();}
  function schoolModal(id){const s=byId.get(id);if(!s)return;const games=data.games.filter(g=>g.teamAId===id||g.teamBId===id);const source=sources.get(s.sourceId);modal(esc(s.name),`<div class="modal-team-head">${crest(s,true)}<div><p>UIL ${s.classification} · ${period(s.alignmentPeriod)} alignment</p><p>Directory listing · ${follow(s)}</p></div></div><div class="modal-body"><div class="record-fields"><div><span>Classification</span><strong>${s.classification} (2026–28)</strong></div><div><span>Reported enrollment</span><strong>${count(s.enrollment)}</strong></div>${Object.entries(s.districts).map(([id,d])=>`<div><span>${esc(officialSports.find(x=>x.id===id).name)} district</span><strong>${d}</strong></div>`).join('')}${s.footballFormat?`<div><span>Football format / division</span><strong>${s.footballFormat}${s.footballDivision?' · Division '+s.footballDivision:' · Division not assigned in listing'}</strong></div>`:''}</div><p>Program districts are from the UIL listing. Rosters and gender-specific participation are not included. The badge uses initials and is not an official school logo.</p><div class="source-note">${external(source.url+'#page='+s.sourcePage,`UIL source · page ${s.sourcePage}`)}<br>Retrieved ${esc(dateTime(source.fetchedAt))}</div><h3>Imported championship appearances</h3>${games.length?games.map(g=>`<button class="modal-game" data-action="game" data-id="${g.id}"><span>${period(g.season)} · ${esc(g.conference)}</span><strong>${g.teamAScore}–${g.teamBScore} · ${g.winnerId===id?'Champion':'Runner-up'} ↗</strong></button>`).join(''):'<p>No appearance in the imported finals. This does not mean the school played no games.</p>'}<div class="injury-note"><strong>Season record, power rating & prediction: Not available</strong><br>Historical championship appearances are not a complete season record.</div><div class="injury-note"><strong>Injuries & availability: Unknown</strong><br>No player health information or absence reports are collected in this release.</div></div>`,'school',id);}
  function gameModal(id){const g=data.games.find(x=>x.id===id);if(!g)return;const source=sources.get(g.sourceId);modal(`${esc(g.teamAName)} vs. ${esc(g.teamBName)}`,`<p class="modal-subtitle">${period(g.season)} · ${esc(g.conference)} · State championship final</p><div class="compare-result"><div class="result-names"><button data-action="school" data-id="${g.teamAId}">${esc(g.teamAName)}</button><button data-action="school" data-id="${g.teamBId}">${esc(g.teamBName)}</button></div><div class="predicted-score">${g.teamAScore} : ${g.teamBScore}</div><p style="text-align:center">FINAL · Historical result · Not live</p></div><div class="modal-body"><h3>Champion: ${esc(g.teamAName)}</h3>${g.notes?`<p>${esc(g.notes)}</p>`:''}<p>Classification is from ${period(g.season)}. The school directory uses the separate 2026–28 alignment. Team order indicates champion and runner-up, not home and away.</p><p>Exact game date and venue are not imported in this snapshot.</p><div class="source-note">${sourceLink(source,'UIL Football State Archives')}${g.boxScoreUrl?'<br>'+external(g.boxScoreUrl,'Official box score'):''}<br>Retrieved ${esc(dateTime(source.fetchedAt))}</div><h3>Predictions & player availability</h3><p>Not available. This historical result is never updated by the demo simulator.</p></div>`,'game',id);}
  function sourcesModal(){modal('Know what’s behind the data.',`<div class="modal-body"><p>This independent app imports public facts from UIL. It is not affiliated with or endorsed by UIL.</p><h3>What is included?</h3><p>${esc(data.coverage.schools)}</p><p>${esc(data.coverage.programs)}</p><p>${esc(data.coverage.results)}</p><h3>What is missing?</h3><p>${esc(data.coverage.ratings)} No live score feed, regular-season schedules, news feed, city directory, verified rosters, or injury reports are connected.</p><h3>Two different time periods</h3><p>School profiles use 2026–28 classification and district assignments. Games retain 2025–26 or 2024–25 championship classifications. A historical result is not a current-season score.</p><h3>Source documents</h3>${data.sources.map(s=>`<div class="source-note"><strong>${esc(s.title)}</strong><br>${sourceLink(s,'Open source')}<br>${esc(s.period)}<br>Retrieved ${esc(dateTime(s.fetchedAt))}<details><summary>Source file fingerprint (SHA-256)</summary><code>${esc(s.sha256)}</code></details></div>`).join('')}<h3>Data updates</h3><p>This is a published snapshot. Reloading reloads the same published dataset; it does not fetch new UIL scores. The source import command validates records before replacing the snapshot. Invalid imports keep the last good dataset.</p><h3>Privacy & saved schools</h3><p>Followed school IDs are stored only in this browser, separately from demo favorites. No account or cross-device sync is available.</p><a class="secondary-button download-link" href="./data/official.json" download="texas-uil-public-data.json">Download this data snapshot ↓</a></div>`,'sources');}
  function clear(){state.classification=state.district=state.format='all';state.query='';state.page=1;$('#search').value='';render();}
  function exportDirectory(){const schools=selectedSchools().filter(s=>state.view!=='favorites'||state.follows.has(s.id));const url=URL.createObjectURL(new Blob([directoryCsv(schools,directorySource.url,data.fetchedAt)],{type:'text/csv;charset=utf-8;'}));const a=document.createElement('a');a.href=url;a.download='texas-uil-schools-2026-28.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast(`Exported ${count(schools.length)} sourced school listings`);}
  function followSchool(id){if(!byId.has(id))return;const saved=state.follows.has(id);if(saved)state.follows.delete(id);else state.follows.add(id);try{storage.setItem('txhs:official-school-follows',JSON.stringify([...state.follows]));toast(saved?'School unfollowed':'School followed');}catch{toast('Saved for this session only. Browser storage is blocked.');}nav();renderContent();if(state.modal?.type==='school')schoolModal(id);}
  document.addEventListener('click',event=>{const button=event.target.closest('[data-action]');if(!button||button.disabled)return;const {action,id}=button.dataset;const actions={sport:()=>{state.sport=id;state.page=1;state.district='all';if(!['football','all'].includes(id))state.format='all';render();},school:()=>schoolModal(id),game:()=>gameModal(id),follow:()=>followSchool(id),sources:sourcesModal,about:sourcesModal,'close-modal':closeModal,clear,export:exportDirectory,'view-schools':()=>location.hash='teams','view-games':()=>location.hash='games','game-status':()=>{state.gameStatus=id;renderContent();},page:()=>{state.page=Number(id);renderContent();$('#content').scrollIntoView({block:'start'});}};actions[action]?.();});
  $('#search').addEventListener('input',event=>{state.query=event.target.value;state.page=1;shell();renderContent();});
  $('#classification').addEventListener('change',event=>{state.classification=event.target.value;state.page=1;render();});
  $('#region').addEventListener('change',event=>{state.district=event.target.value;state.page=1;render();});
  $('#gender').addEventListener('change',event=>{state.format=event.target.value;state.page=1;render();});
  document.addEventListener('change',event=>{if(event.target.id==='result-season'){state.season=event.target.value;render();}});
  $('#modal').addEventListener('close',()=>state.modal=null);
  $('#modal').addEventListener('click',event=>{if(event.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)closeModal();}});
  document.addEventListener('keydown',event=>{if(event.key==='/'&&!$('#modal').open&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)){event.preventDefault();$('#search').focus();}});
  function navigate(){const next=location.hash.slice(1);state.view=pages[next]?next:'overview';state.page=1;state.district='all';render();window.scrollTo({top:0,behavior:'instant'});}
  window.addEventListener('hashchange',navigate);
  navigate();
}
